css:
.app {
  display: flex;
  justify-content: center;
  padding: 80px 0;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", sans-serif;
}

/* CARD — PERFECT SQUARE */
.card {
  width: 290px;
  height: auto;
  border-radius: 26px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  cursor: pointer;
}

/* TOP */
.card-top {
  position: relative;
  padding: 20px;
  background: radial-gradient(
      140% 120% at 0% 0%,
      rgba(255, 255, 255, 0.14),
      transparent 45%
    ),
    linear-gradient(180deg, #141414, #050505);
}

/* GLASS HOVER */
.glass {
  position: absolute;
  inset: 0;
  background: radial-gradient(
    140px 120px at 30% 0%,
    rgba(255, 255, 255, 0.22),
    rgba(255, 255, 255, 0.08) 40%,
    transparent 70%
  );
  opacity: 0;
  transition: opacity 0.25s ease;
}

.card:hover .glass {
  opacity: 1;
}

.card-top > *:not(.glass) {
  position: relative;
  z-index: 2;
}

/* META */
.meta {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.55);
  margin-bottom: 14px;
}

/* USER */
.user {
  display: flex;
  gap: 12px;
  margin-bottom: 16px;
}

/* CSS AVATAR (NO IMAGES) */
.avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #444, #111);
  display: flex;
  align-items: center;
  justify-content: center;
}

.avatar-initial {
  color: #fff;
  font-weight: 600;
  font-size: 16px;
}

/* INFO */
.name {
  color: #fff;
  font-weight: 600;
  font-size: 15px;
}

.status {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.7);
}

.dot {
  width: 6px;
  height: 6px;
  background: #6aff6a;
  border-radius: 50%;
}

/* STACKED ACTIONS */
.actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.btn {
  height: 38px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 14px;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.14),
    rgba(255, 255, 255, 0.06)
  );
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.btn.secondary {
  opacity: 0.9;
}

/* EXPANDABLE AREA (INSIDE CARD) */
.card-expand {
  flex: 1;
  background: #0c0c0c;
  overflow: hidden;
  max-height: 0;
  transition: max-height 0.45s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.card:hover .card-expand {
  max-height: 120px;
}

/* EXPAND CONTENT */
.section {
  padding: 14px 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.title {
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  margin-bottom: 4px;
}

.text {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.75);
  line-height: 1.4;
}

/* BOTTOM — ALWAYS VISIBLE */
.card-bottom {
  background: linear-gradient(180deg, #b8ff5a, #7de63b);
  padding: 12px;
  text-align: center;
  font-weight: bold;
  font-size: 13px;
  color: #0b0b0b;
  box-shadow:
    0 12px 30px rgba(120, 255, 80, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.25);
}
